schema:
{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Directory to list. Defaults to the workspace root when omitted."
    }
  }
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Absolute path of the document inside the workspace, e.g. /workspace/docs/world.md"
    }
  },
  "required": ["path"]
}

{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Name of the skill to load, exactly as it appears in the workspace skill list, e.g. \"prose-style\"."
    }
  },
  "required": ["name"]
}
